const Validators: Record<string, (message: Record<string, unknown>) => ValidationResult> = {
  'user_message': validateUserMessage,
  'ping': validatePingMessage,
  'list_sessions': validateListSessionsMessage,
};

export function validateMessage(payload: unknown): ValidationResult {
  if (typeof payload !== 'object' || payload === null) {
    return {valid: false, error: 'Message must be an object'};
  }

  const message = payload as Record<string, unknown>;

  if (typeof message.type !== 'string') {
    return {valid: false, error: 'Message must have a type field'};
  }

  const validator = Validators[message.type];
  if (validator) {
    return validator(message);
  }

  return {valid: false, error: `Unknown message type: ${message.type}`};
}

function validateListSessionsMessage(message: Record<string, unknown>): ValidationResult {
  const limit = validateLimit(message.limit);
  if (limit.error) return {valid: false, error: limit.error};

  const before = validateBefore(message.before);
  if (before.error) return {valid: false, error: before.error};

  return {
    valid: true,
    data: {
      type: 'list_sessions',
      ...(limit.value !== undefined ? {limit: limit.value} : {}),
      ...(before.value !== undefined ? {before: before.value} : {}),
    },
  };
}

function isInvalidLimit(limit: unknown): limit is number {
  return typeof limit !== 'number' || !Number.isInteger(limit) || limit < 1 || limit > 200;
}

function validateLimit(limit: unknown): {value?: number; error?: string} {
  if (limit === undefined) return {};
  if (isInvalidLimit(limit)) {
    return {error: 'Invalid limit: must be an integer between 1 and 200'};
  }
  return {value: limit as number};
}

function validateBefore(before: unknown): {value?: {updatedAt: string | number; sessionId: string}; error?: string} {
  if (before === undefined) return {};
  if (typeof before !== 'object' || before === null) {
    return {error: 'Invalid before: must be an object'};
  }

  const b = before as Record<string, unknown>;
  if (typeof b.sessionId !== 'string' || b.sessionId.length < 1 || b.sessionId.length > 128) {
    return {error: 'Invalid before: sessionId must be 1-128 characters'};
  }
  if (typeof b.updatedAt !== 'string' && typeof b.updatedAt !== 'number') {
    return {error: 'Invalid before: updatedAt must be a string or number'};
  }
  if (isNaN(new Date(b.updatedAt).getTime())) {
    return {error: 'Invalid before: updatedAt must be a valid date'};
  }

  return {value: {updatedAt: b.updatedAt, sessionId: b.sessionId}};
}

